// Reference solution
function lsnAtLeast(replay, token) {
  const toNum = (lsn) => {
    const m = /^([0-9A-Fa-f]{1,8})\/([0-9A-Fa-f]{1,8})$/.exec(lsn);
    if (!m) return null;
    return parseInt(m[1], 16) * 2 ** 32 + parseInt(m[2], 16);
  };
  const a = toNum(replay), b = toNum(token);
  if (a === null || b === null) return null;
  return a >= b;
}
